        <button className="btn" onClick={()=>setShowP(s=>!s)} style={{width:30,height:30,borderRadius:"50%",background:`linear-gradient(135deg,${planColor},${planColor}99)`,border:"none",color:"#fff",fontWeight:800,fontSize:12,display:"flex",alignItems:"center",justifyContent:"center",marginLeft:4,flexShrink:0}}>
