                    <div style={{display:"flex",justifyContent:"space-between",marginBottom:item.total>0&&item.type!=="chd"?10:0}}>
                      <div><div style={{fontSize:14,fontWeight:800}}>{item.label}</div><div style={{fontSize:11,color:"#E84D0E",fontWeight:700,marginTop:2}}>{item.line}</div></div>
                      <div style={{textAlign:"right"}}><div style={{fontSize:17,fontWeight:800,color:item.claimable>0?"#111":"#ccc"}}>{fmt(item.claimable)}</div><div style={{fontSize:10,color:"#aaa"}}>{item.type==="don"?"tax credit":"claimable"}</div></div>
                    </div>
                    {item.total>0&&item.type==="med"&&<div style={{background:"#F8F7F4",borderRadius:10,padding:"10px 12px",fontSize:12,color:"#555",lineHeight:1.8}}><div style={{display:"flex",justifyContent:"space-between"}}><span>Total paid</span><span style={{fontWeight:700}}>{fmt(item.total)}</span></div><div style={{display:"flex",justifyContent:"space-between"}}><span>3% threshold</span><span style={{color:"#E84D0E",fontWeight:700}}>−{fmt(item.threshold)}</span></div><div style={{borderTop:"1px solid #E8E7E3",marginTop:3,paddingTop:3,display:"flex",justifyContent:"space-between"}}><span style={{fontWeight:700}}>Claimable</span><span style={{fontWeight:800}}>{fmt(item.claimable)}</span></div><div style={{display:"flex",justifyContent:"space-between"}}><span>Est. credit ~15%</span><span style={{color:"#16A34A",fontWeight:700}}>{fmt(item.credit)}</span></div></div>}
                    {item.total>0&&item.type==="don"&&<div style={{background:"#F8F7F4",borderRadius:10,padding:"10px 12px",fontSize:12,color:"#555",lineHeight:1.8}}><div style={{display:"flex",justifyContent:"space-between"}}><span>First $200 @ 15%</span><span style={{fontWeight:700}}>{fmt(Math.min(item.total,200)*0.15)}</span></div>{item.total>200&&<div style={{display:"flex",justifyContent:"space-between"}}><span>Rest @ 29%</span><span style={{fontWeight:700}}>{fmt((item.total-200)*0.29)}</span></div>}<div style={{borderTop:"1px solid #E8E7E3",marginTop:3,paddingTop:3,display:"flex",justifyContent:"space-between"}}><span style={{fontWeight:700}}>Total credit</span><span style={{color:"#16A34A",fontWeight:800}}>{fmt(item.credit)}</span></div></div>}
                    {item.total===0&&<div style={{fontSize:12,color:"#ccc",marginTop:6}}>No receipts tagged yet</div>}
                  </div>
                ))}
                <button className="btn" onClick={()=>{if(!isPro){setUpgrade("export");return;}const lines=[`PERSONAL TAX – ONTARIO ${yr}`,`Generated: ${new Date().toLocaleDateString("en-CA")}`,"=".repeat(50),"",`LINE 33099 MEDICAL: paid ${fmt(medTotal)}  threshold −${fmt(medThreshold)}  claimable ${fmt(medClaimable)}  credit ~${fmt(medClaimable*0.15)}`,`LINE 34900 DONATIONS: total ${fmt(donTotal)}  credit ${fmt(donCredit)}`,`LINE 21400 CHILDCARE: total ${fmt(chdTotal)}  CRA max $8,000/child`,"","─".repeat(50),"⚠️ Reference only. Consult CPA before filing."].join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([lines],{type:"text/plain"}));a.download=`personal-tax-${yr}.txt`;a.click();}} style={{width:"100%",padding:"15px",borderRadius:14,background:isPro?"linear-gradient(135deg,#E84D0E,#F97316)":"#ECEAE6",color:isPro?"#fff":"#aaa",fontSize:14,fontWeight:800,fontFamily:"'Syne',sans-serif",marginBottom:10,display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>
                  {!isPro&&"🔒 "}{isPro?"⬇ Export T1 Report":"Export T1 — Pro only"}
                </button>
              </>
            )}

            {taxView==="corp"&&hasCorp&&(
              <>
                <div style={{background:"linear-gradient(135deg,#1E1B4B,#312E81)",color:"#fff",borderRadius:20,padding:"20px 22px",marginBottom:12,boxShadow:"0 6px 24px rgba(49,46,129,.35)"}}>
                  <div style={{fontSize:10,color:"#818CF8",letterSpacing:".09em",marginBottom:8}}>T2 CORPORATION · {yr}</div>
                  <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14,marginBottom:12}}><div><div style={{fontSize:10,color:"#6366F1",marginBottom:3}}>GROSS</div><div style={{fontFamily:"'Syne',sans-serif",fontSize:22,fontWeight:800}}>{fmt(corpGrossTotal)}</div></div><div><div style={{fontSize:10,color:"#6366F1",marginBottom:3}}>DEDUCTIBLE</div><div style={{fontFamily:"'Syne',sans-serif",fontSize:22,fontWeight:800,color:"#A5B4FC"}}>{fmt(corpDeductTotal)}</div></div></div>
                  <div style={{height:"1px",background:"rgba(255,255,255,.08)",marginBottom:12}}/>
                  <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14}}><div><div style={{fontSize:10,color:"#6366F1",marginBottom:3}}>HST ITC</div><div style={{fontSize:18,fontWeight:800,color:"#34D399"}}>{fmt(corpHSTTotal)}</div></div><div><div style={{fontSize:10,color:"#6366F1",marginBottom:3}}>ON CORP RATE</div><div style={{fontSize:18,fontWeight:800}}>12.2%</div></div></div>
                </div>
                <div style={{background:"#fff",borderRadius:16,padding:"16px",marginBottom:12,boxShadow:"0 2px 12px rgba(0,0,0,.06)"}}>
                  <div style={{fontSize:10,fontWeight:800,color:"#bbb",letterSpacing:".08em",marginBottom:12}}>HST QUARTERLY RETURN</div>
                  <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
                    {qData.map((q,i)=><div key={i} style={{background:q.hst>0?"#EEF2FF":"#F8F7F4",borderRadius:10,padding:"12px"}}><div style={{fontSize:10,fontWeight:800,color:q.hst>0?"#4338CA":"#bbb",marginBottom:4}}>{q.label}</div><div style={{fontSize:15,fontWeight:800,color:q.hst>0?"#111":"#ccc"}}>{fmt(q.hst)}</div></div>)}
                  </div>
                </div>
                <button className="btn" onClick={()=>{const lines=[`CORP T2 – ONTARIO ${yr}`,`Generated: ${new Date().toLocaleDateString("en-CA")}`,"=".repeat(50),"",`GROSS: ${fmt(corpGrossTotal)}  DEDUCTIBLE: ${fmt(corpDeductTotal)}  HST ITC: ${fmt(corpHSTTotal)}`,"","QUARTERLY HST:",...qData.map(q=>`  ${q.label}: ${fmt(q.hst)}`),"","─".repeat(50),...corpBycat.map(c=>`${c.icon} ${c.label}: ${fmt(c.gross)} gross  ${fmt(c.deductible)} deduct.  ${fmt(c.hst)} HST ITC`),"","⚠️ Reference only. Have accountant review before T2 filing."].join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([lines],{type:"text/plain"}));a.download=`corp-t2-${yr}.txt`;a.click();}} style={{width:"100%",padding:"15px",borderRadius:14,background:"linear-gradient(135deg,#4F46E5,#7C3AED)",color:"#fff",fontSize:14,fontWeight:800,fontFamily:"'Syne',sans-serif",marginBottom:12}}>
                  ⬇ Export Corp T2 Report
                </button>
              </>
            )}
            <div style={{padding:"12px 14px",background:"#FFF3EE",border:"1.5px solid #FFD5C2",borderRadius:12,fontSize:12,color:"#B94A1A",lineHeight:1.6}}>
              ⚠️ Reference only — consult a CPA before filing with CRA.
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// ROOT
// ══════════════════════════════════════════════════════════════════════════════
export default function App() {
  const [state, setState] = useState("loading"); // loading | auth | app
  const [user,  setUser]  = useState(null);

  useEffect(()=>{ db.get("lt_user").then(u=>{ if(u){ setUser(u); setState("app"); } else { setState("auth"); } }); },[]);

  if(state==="loading") return <div style={{minHeight:"100vh",background:"#F5F4F0",display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"sans-serif",fontSize:36}}>🪙</div>;

  if(state==="auth") return (
    <AuthScreen
      onGuest={()=>{ setUser({guest:true,plan:"free"}); setState("app"); }}
      onAuth={u=>{ setUser(u); setState("app"); }}
    />
  );

  return (
    <MainApp
      user={user}
      onSignOut={()=>{ setUser(null); setState("auth"); }}
      onGoAuth={()=>{ setUser(null); setState("auth"); }}
    />
  );
}
